@reference "../../../styles.css";

.app-topbar { @apply flex flex-wrap items-center gap-2 p-4 md:px-6; }
.app-topbar__start { @apply flex min-w-0 flex-1 items-center gap-2; }
.app-topbar__menu { @apply shrink-0; }
.app-topbar__crumbs { @apply min-w-0; }
.app-topbar__crumb-list { @apply flex min-w-0 flex-wrap items-center gap-2; }
.app-topbar__crumb { @apply min-w-0; }
.app-topbar__separator { @apply block; }
